#!/usr/bin/env node
// Compiles the skill into portable files for agents other than Claude.
//
//   node build.mjs           write AGENTS.md, export/wugweb-engineer.md, adapters/ and agents/
//   node build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, metadata.json and docs/skills/STANDING-RULES.md (the home
// file for the owner's rules). Each export carries a marked copy of that file; test.mjs fails
// if a copy drifts. Never edit the outputs by hand.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const HOME = path.resolve(dir, '../../../docs/skills/STANDING-RULES.md');
const read = (p) => fs.readFileSync(path.join(dir, p), 'utf8');
const banner = '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->';

export function rulesBlock() {
  if (!fs.existsSync(HOME)) throw new Error('docs/skills/STANDING-RULES.md not found; build inside the site repo');
  return fs.readFileSync(HOME, 'utf8').replace(/^# .*\n/, '').trim();
}

function parts() {
  const skill = read('SKILL.md');
  const front = /^---\n([\s\S]*?)\n---\n/.exec(skill);
  if (!front) throw new Error('SKILL.md has no frontmatter');
  const name = /^name:\s*(\S+)\s*$/m.exec(front[1])?.[1];
  const descRaw = /^description:\s*(".*")\s*$/m.exec(front[1])?.[1];
  if (!name || !descRaw) throw new Error('SKILL.md needs name and a double-quoted description');
  const meta = JSON.parse(read('metadata.json'));
  const version = /version:\s*"?([\d.]+)"?/.exec(front[1])[1];
  if (meta.version !== version) throw new Error(`metadata.json version ${meta.version} differs from SKILL.md ${version}`);
  const body = skill.slice(front[0].length).trim();
  const indexed = [...body.matchAll(/`references\/([a-z0-9-]+\.md)`/g)].map((m) => m[1]);
  const onDisk = fs.readdirSync(path.join(dir, 'references')).filter((f) => f.endsWith('.md')).sort();
  const refs = [...new Set([...indexed, ...onDisk])].filter((f) => onDisk.includes(f));
  return { name, description: JSON.parse(descRaw), meta, version, body, refs };
}

const demote = (md) => md.replace(/^(#{1,5}) /gm, '#$1 ');

export function render(kind) {
  const { name, description, meta, version, body, refs } = parts();
  const rules = rulesBlock();
  const rulesSection = `## Owner's standing rules\n\nCopied from \`docs/skills/STANDING-RULES.md\`. That file is the source; if this block differs, that file wins.\n\n${rules}`;
  const refText = refs.map((f) => `<!-- references/${f} -->\n\n${demote(read('references/' + f).trim())}\n`).join('\n');
  if (kind === 'agents' || kind === 'export') {
    const head = kind === 'agents'
      ? `# ${name} (single-file export for other tools, v${version})`
      : `# ${name} (single-file export, v${version})`;
    return [banner, '', head, '', `${meta.organization} · ${meta.date}`, '', meta.abstract, '',
      'Read the skill first, then the reference a mode names. The scripts are not inside this file; without them, follow the runbook steps by hand and say the result is a manual check.', '',
      rulesSection, '', '---', '', body.replace(/^# .*$/m, '# The skill'), '', '---', '', '# Reference material', '',
      'The sections below are the skill\'s `references/` files, so this document works alone. Where the text above says "read `references/x.md`", read the section of that name below.', '',
      refText].join('\n');
  }
  if (kind === 'cursor') {
    return ['---', `description: ${JSON.stringify(description)}`,
      'globs: ["**/sanity/schemaTypes/**", "**/scripts/sync-*.mjs", "**/backups/**", "**/skills/' + name + '/**"]',
      'alwaysApply: false', '---', '', banner, '', body, ''].join('\n');
  }
  if (kind === 'chatgpt') {
    return [banner, '', '# Instructions for a custom GPT or project', '',
      'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.', '',
      '```',
      'You govern changes to the data behind wugweb.com, using the method in the',
      'uploaded file AGENTS.md: Sanity documents, the Sanity schema, the Notion to',
      'Sanity sync scripts, backups and undo. Read AGENTS.md before any such task and',
      'name the mode you are running in the first line of the reply.',
      '',
      'This list is a short form of the owner\'s standing rules, which AGENTS.md',
      'includes in full. If they differ, AGENTS.md wins.',
      '',
      'Always:',
      '- Read first and report the count, computed, never estimated.',
      '- Back up the documents before any change; name the backup.',
      '- Plan one field at a time and show it as current -> proposed, with what',
      '  a visitor will see and the undo.',
      '- Wait for the owner\'s go on that exact plan. "Now" is not a go to a plan',
      '  the owner has not seen.',
      '- Patch with a revision guard, then read again and check every value.',
      '- Say which skill owns a decision you are asked to make: field decisions',
      '  are wugweb-strategy\'s, search values are wugweb-seo\'s, visible wording is',
      '  wugweb-work\'s. If it is not decided, say so.',
      '- British English, sentence case. Reply short and plain, result first.',
      '',
      'Never:',
      '- Delete, create or replace a document, or discard a draft. Propose an',
      '  owner-run route instead.',
      '- Upload, copy, crop, re-encode or remove media.',
      '- Clear a field because the source is empty.',
      '- Echo, write or send on any key or token. Ask the owner to set it in the',
      '  environment the script reads.',
      '- Deploy the schema or the Studio, run a Neon sync, or run a script the',
      '  status list marks "do not run" or "owner only".',
      '- Invent a number, a value or a fact.',
      '',
      'If you can run code, use the scripts named in AGENTS.md. If you cannot, follow',
      'the runbook by hand, show the GROQ query you would run, and label the result',
      'a manual check.',
      '```', ''].join('\n');
  }
  if (kind === 'openai') {
    return ['# Generated by scripts/build.mjs. Do not edit by hand.',
      '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
      'interface:', `  display_name: "${name}"`,
      '  short_description: "Change Wugweb data safely: back up, plan, go, patch, check, undo"',
      '  default_prompt: "Plan the Sanity change I describe as current to proposed, with the backup and the undo, and wait for my go."',
      'policy:', '  allow_implicit_invocation: true', ''].join('\n');
  }
  throw new Error('unknown kind ' + kind);
}

export const OUTPUTS = [
  ['AGENTS.md', 'agents'],
  ['export/wugweb-engineer.md', 'export'],
  ['adapters/cursor/wugweb-engineer.mdc', 'cursor'],
  ['adapters/chatgpt/instructions.md', 'chatgpt'],
  ['agents/openai.yaml', 'openai'],
];

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const [file, kind] of OUTPUTS) {
    const out = render(kind);
    const p = path.join(dir, file);
    if (check) {
      const ok = fs.existsSync(p) && fs.readFileSync(p, 'utf8') === out;
      console.log((ok ? 'fresh ' : 'STALE ') + file);
      if (!ok) stale++;
    } else {
      fs.mkdirSync(path.dirname(p), { recursive: true });
      fs.writeFileSync(p, out);
    }
  }
  if (check) process.exit(stale ? 1 : 0);
  console.log('built ' + OUTPUTS.map((o) => o[0]).join(', '));
}
